  const target = parseLaunchTarget(launchUrl);
  if (target === null) {
    // 不回显原文：启动网址含一次性 token，避免经错误提示/日志扩散
    return { status: 'rejected', authority: '(unknown)', reason: '启动网址无法解析（缺少有效的 token 参数）' };
