      "content": "{\n  \"name\": \"dsh-vscode-panel\",\n  \"displayName\": \"DSH\",\n  \"description\": \"Use DeepSeek Harness (DSH) inside VS Code — embedded web UI, auto-start, one-time-token auth, and file/clipboard/image bridge.\",\n  \"version\": \"0.4.4\",\n  \"l10n\": \"./l10n\",\n  \"publisher\": \"Fengze233\",\n  \"icon\": \"assets/icon.png\",\n  \"license\": \"MIT\",\n  \"engines\": {\n    \"vscode\": \"^1.91.0\"\n  },\n  \"extensionKind\": [\n    \"workspace\",\n    \"ui\"\n  ],\n  \"categories\": [\n    \"AI\",\n    \"Chat\",\n    \"Other\"\n  ],\n  \"main\": \"./out/extension.js\",\n  \"uninstall\": \"node ./out/uninstall.js\",\n  \"activationEvents\": [\n    \"onView:dsh.panel\",\n    \"onView:dsh.panel.secondary\",\n    \"onCommand:dsh.openPanel\",\n    \"onCommand:dsh.openSecondary\",\n    \"onCommand:dsh.openExternal\",\n    \"onCommand:dsh.restart\",\n    \"onCommand:dsh.stop\",\n    \"onCommand:dsh.copyUrl\",\n    \"onCommand:dsh.showLogs\",\n    \"onCommand:dsh.bridge.retry\",\n    \"onCommand:dsh.bridge.uninstall\",\n    \"onCommand:dsh.cleanupImageCache\",\n    \"onCommand:dsh.copyLogs\"\n  ],\n  \"contributes\": {\n    \"viewsContainers\": {\n      \"activitybar\": [\n        {\n          \"id\": \"dsh\",\n          \"title\": \"%dsh.container.title%\",\n          \"icon\": \"assets/whale-icon.svg\"\n        }\n      ],\n      \"secondarySidebar\": [\n        {\n          \"id\": \"dsh-secondary\",\n          \"title\": \"%dsh.container.title%\",\n          \"icon\": \"assets/whale-icon.svg\"\n        }\n      ]\n    },\n    \"views\": {\n      \"dsh\": [\n        {\n          \"id\": \"dsh.panel\",\n          \"name\": \"%dsh.view.panel.name%\",\n          \"type\": \"webview\"\n        }\n      ],\n      \"dsh-secondary\": [\n        {\n          \"id\": \"dsh.panel.secondary\",\n          \"name\": \"%dsh.view.panelSecondary.name%\",\n          \"type\": \"webview\"\n        }\n      ]\n    },\n    \"walkthroughs\": [\n      {\n        \"id\": \"dsh.getStarted\",\n        \"title\": \"%dsh.walkthrough.title%\",\n        \"description\": \"%dsh.walkthrough.description%\",\n        \"steps\": [\n          {\n            \"id\": \"dsh.openPanel\",\n            \"title\": \"%dsh.walkthrough.step.title%\",\n            \"description\": \"%dsh.walkthrough.step.description%\",\n            \"media\": {\n              \"image\": \"assets/icon.png\"\n            },\n            \"completionEvents\": [\n              \"onCommand:dsh.openPanel\"\n            ]\n          }\n        ]\n      }\n    ],\n    \"commands\": [\n      {\n        \"command\": \"dsh.openPanel\",\n        \"title\": \"%dsh.cmd.openPanel.title%\",\n        \"icon\": \"$(panel)\"\n      },\n      {\n        \"command\": \"dsh.openSecondary\",\n        \"title\": \"%dsh.cmd.openSecondary.title%\",\n        \"icon\": \"$(layout-sidebar-right)\"\n      },\n      {\n        \"command\": \"dsh.openExternal\",\n        \"title\": \"%dsh.cmd.openExternal.title%\",\n        \"icon\": \"$(link-external)\"\n      },\n      {\n        \"command\": \"dsh.restart\",\n        \"title\": \"%dsh.cmd.restart.title%\",\n        \"icon\": \"$(refresh)\"\n      },\n      {\n        \"command\": \"dsh.stop\",\n        \"title\": \"%dsh.cmd.stop.title%\",\n        \"icon\": \"$(debug-stop)\"\n      },\n      {\n        \"command\": \"dsh.copyUrl\",\n        \"title\": \"%dsh.cmd.copyUrl.title%\",\n        \"icon\": \"$(copy)\"\n      },\n      {\n        \"command\": \"dsh.showLogs\",\n        \"title\": \"%dsh.cmd.showLogs.title%\",\n        \"icon\": \"$(output)\"\n      },\n      {\n        \"command\": \"dsh.copyLogs\",\n        \"title\": \"%dsh.cmd.copyLogs.title%\",\n        \"category\": \"DSH\"\n      },\n      {\n        \"command\": \"dsh.bridge.retry\",\n        \"title\": \"%dsh.cmd.bridgeRetry.title%\"\n      },\n      {\n        \"command\": \"dsh.bridge.uninstall\",\n        \"title\": \"%dsh.cmd.bridgeUninstall.title%\"\n      },\n      {\n        \"command\": \"dsh.cleanupImageCache\",\n        \"title\": \"%dsh.cmd.cleanupImageCache.title%\",\n        \"category\": \"DSH\"\n      },\n      {\n        \"command\": \"dsh.openFromTitle\",\n        \"title\": \"%dsh.cmd.openFromTitle.title%\",\n        \"icon\": \"assets/whale-icon-bg.svg\"\n      }\n    ],\n    \"menus\": {\n      \"editor/title\": [\n        {\n          \"command\": \"dsh.openFromTitle\",\n          \"group\": \"navigation@0\",\n          \"when\": \"editorIsOpen\"\n        }\n      ],\n      \"view/title\": [\n        {\n          \"command\": \"dsh.openExternal\",\n          \"when\": \"view == dsh.panel || view == dsh.panel.secondary\",\n          \"group\": \"navigation@1\"\n        },\n        {\n          \"command\": \"dsh.restart\",\n          \"when\": \"view == dsh.panel || view == dsh.panel.secondary\",\n          \"group\": \"navigation@2\"\n        },\n        {\n          \"command\": \"dsh.stop\",\n          \"when\": \"view == dsh.panel || view == dsh.panel.secondary\",\n          \"group\": \"navigation@3\"\n        },\n        {\n          \"command\": \"dsh.copyUrl\",\n          \"when\": \"view == dsh.panel || view == dsh.panel.secondary\",\n          \"group\": \"navigation@4\"\n        },\n        {\n          \"command\": \"dsh.showLogs\",\n          \"when\": \"view == dsh.panel || view == dsh.panel.secondary\",\n          \"group\": \"navigation@5\"\n        }\n      ]\n    },\n    \"configuration\": {\n      \"title\": \"DSH\",\n      \"properties\": {\n        \"dsh.profile\": {\n          \"type\": \"string\",\n          \"default\": \"web\",\n          \"minLength\": 1,\n          \"pattern\": \"^(?!\\\\.{1,2}$)[A-Za-z0-9._][A-Za-z0-9._-]*$\",\n          \"markdownDescription\": \"%dsh.config.profile%\"\n        },\n        \"dsh.launchPreference\": {\n          \"type\": \"string\",\n          \"enum\": [\n            \"auto\",\n            \"npm\",\n            \"desktop\"\n          ],\n          \"default\": \"auto\",\n          \"markdownDescription\": \"%dsh.config.launchPreference%\"\n        },\n        \"dsh.desktopCommandPath\": {\n          \"type\": \"string\",\n          \"default\": \"\",\n          \"markdownDescription\": \"%dsh.config.desktopCommandPath%\"\n        },\n        \"dsh.host\": {\n          \"type\": \"string\",\n          \"default\": \"127.0.0.1\",\n          \"enum\": [\n            \"127.0.0.1\",\n            \"localhost\",\n            \"[::1]\"\n          ],\n          \"markdownDescription\": \"%dsh.config.host%\"\n        },\n        \"dsh.port\": {\n          \"type\": \"number\",\n          \"default\": 3080,\n          \"minimum\": 0,\n          \"maximum\": 65535,\n          \"markdownDescription\": \"%dsh.config.port%\"\n        },\n        \"dsh.autoStart\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"markdownDescription\": \"%dsh.config.autoStart%\"\n        },\n        \"dsh.stopOnExit\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"markdownDescription\": \"%dsh.config.stopOnExit%\"\n        },\n        \"dsh.extraArgs\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"type\": \"string\"\n          },\n          \"default\": [],\n          \"markdownDescription\": \"%dsh.config.extraArgs%\"\n        },\n        \"dsh.bridge.enabled\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"markdownDescription\": \"%dsh.config.bridgeEnabled%\"\n        },\n        \"dsh.workspaceRootIndex\": {\n          \"type\": \"number\",\n          \"default\": 0,\n          \"minimum\": 0,\n          \"markdownDescription\": \"%dsh.config.workspaceRootIndex%\"\n        },\n        \"dsh.bridge.silenceWarning\": {\n          \"type\": \"boolean\",\n          \"default\": false,\n          \"markdownDescription\": \"%dsh.config.bridgeSilenceWarning%\"\n        },\n        \"dsh.executablePath\": {\n          \"type\": \"string\",\n          \"default\": \"\",\n          \"markdownDescription\": \"%dsh.config.executablePath%\"\n        },\n        \"dsh.openInBrowser\": {\n          \"type\": \"boolean\",\n          \"default\": false,\n          \"markdownDescription\": \"%dsh.config.openInBrowser%\"\n        },\n        \"dsh.remote.enabled\": {\n          \"type\": \"boolean\",\n          \"default\": false,\n          \"markdownDescription\": \"%dsh.config.remoteEnabled%\"\n        },\n        \"dsh.image.fallback\": {\n          \"type\": \"boolean\",\n          \"default\": true,\n          \"markdownDescription\": \"%dsh.config.imageFallback%\"\n        },\n        \"dsh.startTimeoutMs\": {\n          \"type\": \"number\",\n          \"default\": 45000,\n          \"minimum\": 5000,\n          \"maximum\": 600000,\n          \"markdownDescription\": \"%dsh.config.startTimeoutMs%\"\n        },\n        \"dsh.env\": {\n          \"type\": \"object\",\n          \"default\": {},\n          \"additionalProperties\": {\n            \"type\": \"string\"\n          },\n          \"markdownDescription\": \"%dsh.config.env%\"\n        },\n        \"dsh.useEnvProxy\": {\n          \"type\": \"boolean\",\n          \"default\": false,\n          \"markdownDescription\": \"%dsh.config.useEnvProxy%\"\n        },\n        \"dsh.panel.zoomLevel\": {\n          \"type\": \"number\",\n          \"default\": 1,\n          \"enum\": [\n            0.5,\n            0.55,\n            0.6,\n            0.65,\n            0.7,\n            0.75,\n            0.8,\n            0.85,\n            0.9,\n            0.95,\n            1,\n            1.05,\n            1.1,\n            1.15,\n            1.2,\n            1.25,\n            1.3,\n            1.35,\n            1.4,\n            1.45,\n            1.5\n          ],\n          \"enumDescriptions\": [\n            \"50%（最小，一屏看最多内容）\",\n            \"55%\",\n            \"60%\",\n            \"65%\",\n            \"70%\",\n            \"75%\",\n            \"80%\",\n            \"85%\",\n            \"90%\",\n            \"95%\",\n            \"100%（默认，与 DSH 原始大小一致）\",\n            \"105%\",\n            \"110%\",\n            \"115%\",\n            \"120%\",\n            \"125%\",\n            \"130%\",\n            \"135%\",\n            \"140%\",\n            \"145%\",\n            \"150%（最大，适合演示）\"\n          ],\n          \"markdownDescription\": \"%dsh.config.panelZoom%\"\n        }\n      }\n    }\n  },\n  \"scripts\": {\n    \"compile\": \"node scripts/build.mjs\",\n    \"watch\": \"node scripts/build.mjs --watch\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"test\": \"node scripts/build.mjs --test && node --test \\\"out/test/**/*.test.js\\\"\",\n    \"package\": \"npm run compile && vsce package -o dsh-vscode.vsix\"\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^22.0.0\",\n    \"@types/vscode\": \"^1.85.0\",\n    \"@vscode/vsce\": \"^3.0.0\",\n    \"esbuild\": \"^0.25.0\",\n    \"typescript\": \"^5.5.0\"\n  },\n  \"keywords\": [\n    \"deepseek\",\n    \"dsh\",\n    \"deepseek-harness\",\n    \"ai\",\n    \"assistant\",\n    \"coding-agent\",\n    \"ai-coding\",\n    \"vscode-extension\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Fengze233/dsh-vscode.git\"\n  },\n  \"homepage\": \"https://github.com/Fengze233/dsh-vscode#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/Fengze233/dsh-vscode/issues\"\n  }\n}\n"
    },
    {
      "path": "src/panel/provider.ts",
      "content": "// src/panel/provider.ts — 侧边栏面板：iframe 与占位页切换\nimport * as vscode from 'vscode';\nimport { randomUUID } from 'node:crypto';\nimport * as nodeFs from 'node:fs/promises';\nimport { ServiceManager } from '../service/manager';\nimport { handleBridgeMessage } from '../bridge/host';\nimport { classifyRemote, toLocalhostUrl, type RemoteKind } from '../remote';\nimport { t } from '../i18n';\nimport {\n  loadingPage,\n  errorPage,\n  disconnectedPage,\n  stoppedPage,\n  readyPage,\n  remoteDisabledPage,\n  authRequiredPage,\n  type PanelMessage,\n  type PageCtx,\n} from './html';\n\n/** 会话/代理状态（扩展注入）：驱动 ready 分支的三态渲染 */\nexport type AuthUiState = 'ok' | 'needed' | 'pending';\n\n/** 面板增强接线（v0.4.0 鉴权适配；均可选，缺省保持旧行为） */\nexport interface PanelProviderUiOpts {\n  /** 会话状态 getter：ok=可直接进 iframe；needed=显示「需要登录」引导页；pending/undefined=加载中 */\n  authState?: () => AuthUiState | undefined;\n  /** iframe 基地址覆盖（本地代办代理就绪后返回其 baseUrl；null=回退 dsh 真实地址） */\n  frameBaseOverride?: () => string | null;\n  /** 「需要登录」页提交启动网址的回调（扩展校验并兑换） */\n  onAuthUrlSubmit?: (url: string) => void;\n  /** 面板缩放 getter（dsh.panel.zoomLevel，issue #8；缺省 1 = 不缩放） */\n  zoomLevel?: () => number;\n}\n\nexport class DshPanelProvider implements vscode.WebviewViewProvider {\n  private view: vscode.WebviewView | null = null;\n  /** 曾处于 ready：用于区分\"服务断开\"与\"手动停止\"两种占位页 */\n  private wasConnected = false;\n  /** 面板是否已首次打开过（用于一次性回调） */\n  private openedOnce = false;\n  /** 桥接握手 token：一次性防伪凭据，用密码学随机数（不可预测） */\n  private readonly bridgeToken = randomUUID();\n  /** 解析后的本地可达 URL（远程=隧道 URL、本地=原 URL；仅 ready 且远程启用时被设置） */\n  private pendingExternalUrl: string | null = null;\n  /** 渲染代数：递增使进行中的异步 URL 解析过期，防止乱序覆盖 */\n  private renderGen = 0;\n\n  /**\n   * @param manager 服务管理器（面板与服务状态联动）\n   * @param onFirstOpen 面板首次打开时调用一次的回调（用于引导提示，由入口注入）\n   * @param onBridgeAck 桥接握手回执回调（Task 7 评估桥接状态时注入；可选）\n   * @param workspaceRoot 工作区根目录注入函数（openFile 相对路径解析的兜底基准；可选，默认无根）\n   * @param bridgeEnabled 桥接是否启用的 getter（Task 7 由 dsh.bridge.enabled 配置驱动；默认启用，\n   *   disabled 时不注入握手脚本，避免向未安装桥接的 DSH 页面发送无意义的握手）\n   * @param remoteEnabled 是否启用远程（SSH Remote 等）的 getter（v0.3.0，默认关闭）\n   * @param resolveExternalUrl URL→本地可达 URL 解析器（远程走 asExternalUri 隧道；默认原样返回）\n   * @param imageFallback 是否启用非视觉模型图片降级（v0.3.0，默认开）\n   */\n  constructor(\n    private manager: ServiceManager,\n    private onFirstOpen?: () => void,\n    private onBridgeAck?: (ok: boolean, version?: string) => void,\n    private workspaceRoot: () => string | undefined = () => undefined,\n    private bridgeEnabled: () => boolean = () => true,\n    private remoteEnabled: () => boolean = () => false,\n    private resolveExternalUrl: (url: string) => Promise<string> = async (u) => u,\n    private imageFallback: () => boolean = () => true,\n    private ui: PanelProviderUiOpts = {},\n  ) {\n    // 订阅状态变化，重绘面板（iframe 与占位页由状态驱动，无白屏路径）\n    manager.onChange(() => void this.handleStateChange());\n  }\n\n  /** 强制按最新状态重渲染（会话兑换完成/代理就绪后由扩展调用，弥补 onChange 之外的触发源） */\n  refresh(): void {\n    void this.handleStateChange();\n  }\n\n  resolveWebviewView(view: vscode.WebviewView): void {\n    this.view = view;\n    // enableScripts 允许占位页的内联按钮脚本（nonce 放行）运行。\n    // 注意：retainContextWhenHidden 不在这里设置——它不是 WebviewOptions 字段，\n    // 由 Task 10 注册视图时通过第三参数传入（隐藏面板时保留 iframe 会话）。\n    view.webview.options = { enableScripts: true };\n    view.webview.onDidReceiveMessage((msg: PanelMessage) => this.onMessage(msg));\n    if (!this.openedOnce) {\n      this.openedOnce = true;\n      this.onFirstOpen?.(); // 首次打开：触发一次性引导（如\"移到右侧栏\"提示）\n    }\n    this.render();\n    // 远程窗口且未启用远程支持：仅显示占位页，绝不在此窗口启动远端 dsh 服务。\n    if (this.remoteWindowDisabled()) return;\n    // 面板打开即确保服务运行：复用已有或自动启动。\n    void this.manager.ensureRunning();\n  }\n\n  /**\n   * 当前窗口是否处于「远程隧道但未启用」状态：仅 SSH Remote/容器等需要隧道的远程窗口\n   * （remoteKind='tunneled'）且 dsh.remote.enabled=false 时成立。\n   * WSL（issue #13-3）不是隧道远程：vscode-server/dsh 同在一台 WSL 内、靠 localhost 转发直连，\n   * 不需要（也不支持）asExternalUri——WSL 窗口与本地窗口同样默认可用，不拦。\n   * 该状态下不拉起远端服务、不建隧道，仅展示引导占位页。\n   */\n  private remoteWindowDisabled(): boolean {\n    return this.remoteKind() === 'tunneled' && !this.remoteEnabled();\n  }\n\n  /** 当前窗口的远程分类（local / wsl / tunneled） */\n  private remoteKind(): RemoteKind {\n    return classifyRemote(vscode.env.remoteName);\n  }\n\n  /** 当前展示用的本地可达 URL（供「复制网址」命令使用；未解析时返回 null 由调用方回退原 URL） */\n  getDisplayUrl(): string | null {\n    return this.pendingExternalUrl;\n  }\n\n  /** 处理面板内按钮消息（全部转交给 manager 或对应命令） */\n  private onMessage(msg: PanelMessage): void {\n    switch (msg.type) {\n      case 'retry':\n      case 'reconnect':\n        void this.manager.ensureRunning();\n        break;\n      case 'restart':\n        void this.manager.restart();\n        break;\n      case 'stop':\n        this.wasConnected = false;\n        void this.manager.stop();\n        break;\n      case 'openExternal':\n        void vscode.commands.executeCommand('dsh.openExternal');\n        break;\n      case 'copyUrl':\n        void vscode.commands.executeCommand('dsh.copyUrl');\n        break;\n      case 'showLogs':\n        void vscode.commands.executeCommand('dsh.showLogs');\n        break;\n      case 'openSettings':\n        // 远程未启用占位页的「打开设置」按钮：聚焦 dsh.remote.enabled 设置\n        void vscode.commands.executeCommand('workbench.action.openSettings', 'dsh.remote.enabled');\n        break;\n      case 'authSubmitLaunchUrl':\n        // 「需要登录」引导页提交的启动网址：转交扩展校验与兑换（成败反馈在扩展侧提示）\n        this.ui.onAuthUrlSubmit?.(msg.url);\n        break;\n      case 'bridgeCopyText':\n        // 桥接剪贴板消息：VS Code 会拦截跨源 iframe 的原生 clipboard API，\n        // 这里由扩展宿主写系统剪贴板，并回执给 iframe 收尾其 writeText Promise。\n        void this.copyTextToClipboard(msg);\n        break;\n      case 'bridgeReadText':\n        // 剪贴板读取：扩展宿主读系统剪贴板（无 webview 权限限制），\n        // 回执给 iframe 供其 Cmd+V 粘贴兜底使用。\n        void this.readTextFromClipboard(msg);\n        break;\n      case 'bridgeOpenExternal':\n      case 'bridgeOpenFile':\n      case 'bridgeSaveImage':\n      case 'bridgeDeleteImages':\n        // 桥接消息统一走 host 的 handleBridgeMessage（外链/文件/图片落盘与删除，白名单与路径安全在 host 层）\n        void handleBridgeMessage(msg, this.bridgeDeps());\n        break;\n      case 'bridgeAck':\n        // 握手回执：通知注入的回调（Task 7 据此评估桥接状态；version 供日志确认桥接代码版本）\n        this.onBridgeAck?.(msg.ok, msg.version);\n        break;\n    }\n  }\n\n  /** 桥接落盘/删除依赖：图片缓存写文件/删文件（node:fs/promises）与回执投递（webview.postMessage） */\n  private bridgeDeps(): Parameters<typeof handleBridgeMessage>[1] {\n    return {\n      openExternal: (u) => vscode.env.openExternal(vscode.Uri.parse(u)),\n      // 用 vscode.open 而不是 window.showTextDocument：后者只能开文本编辑器，\n      // 点图片/PDF 会抛「File seems to be binary and cannot be opened as text」（issue #33）。\n      // vscode.open 由 VS Code 自选编辑器：文本→文本编辑器、图片→图片预览、PDF→内建 PDF 预览、\n      // 未知二进制→占位页（提示而非报错）。依赖契约仍为 Thenable<void>，故不返回其执行结果。\n      openTextDocument: async (p) => {\n        await vscode.commands.executeCommand('vscode.open', vscode.Uri.file(p), { preview: false });\n      },\n      // 用户提示统一走 vscode.window.showWarningMessage（host 层不 import vscode，保持纯逻辑可单测）\n      showWarning: (m) => void vscode.window.showWarningMessage(m),\n      workspaceRoot: this.workspaceRoot(), // 工作区根目录：openFile 相对路径解析的兜底基准\n      // 图片缓存：以 base64 写入（node:fs/promises 支持 base64 编码字符串）；删除用 unlink\n      writeFile: async (p, b64) => {\n        await nodeFs.writeFile(p, Buffer.from(b64, 'base64'));\n      },\n      rmFile: async (p) => {\n        await nodeFs.unlink(p);\n      },\n      // 回执：由顶层握手脚本转发回 iframe（saveImageAck / deleteImagesAck）\n      reply: async (m) => {\n        await this.view?.webview.postMessage(m);\n      },\n    };\n  }\n\n  /** 剪贴板桥接：扩展宿主写系统剪贴板，完成后回执给 webview（由顶层脚本转发给 iframe） */\n  private async copyTextToClipboard(msg: Extract<PanelMessage, { type: 'bridgeCopyText' }>): Promise<void> {\n    let ok = false;\n    try {\n      await vscode.env.clipboard.writeText(msg.text);\n      ok = true;\n    } catch {\n      // 写剪贴板失败：回执 ok=false，iframe 侧会 reject