      "path": "src/remote.ts",
      "content": "// src/remote.ts — 远程（SSH Remote/WSL/Dev Container/Codespaces）场景检测与 URL 隧道解析\n// 纯逻辑 + 注入式 vscode API（asExternalUri），便于 node:test 单测。\n// 设计背景（v0.3.0 需求 1）：在远程窗口中，扩展宿主运行在远端，spawn 的 dsh 跑在远端\n// 127.0.0.1:<port>；而面板 iframe 在本地浏览器里无法直接访问远端回环地址。\n// 做法：调用 vscode.env.asExternalUri 让 VS Code 自动在「远端 127.0.0.1:<port> ↔ 本地」建立\n// 端口转发隧道，返回本地可达的 URI；本地（非远程）时 asExternalUri 原样返回，无需分支。\n//\n// WSL 特判（issue #13-3）：Remote-WSL 里 vscode-server / webview / dsh 全在同一 WSL 内，\n// 127.0.0.1 直达、不需要隧道；且 asExternalUri 对 WSL 的 127.0.0.1 返回原样（不建隧道）。\n// WSL 与 SSH Remote 的本质差异：WSL 有 Windows→WSL 的 localhost 转发（VS Code Remote-WSL\n// 常态可用），因此 WSL 场景把 iframe 地址的 host 从 127.0.0.1 换成 localhost 即可，\n// 顺带绕开 webview service worker 对 127.0.0.1 iframe 的 origin 重写（见握手脚本注释）。\n\n/** 远程窗口分类：local 本地 / wsl（Remote-WSL：同机直连 + localhost 转发）/ tunneled（SSH 等：需 asExternalUri 隧道） */\nexport type RemoteKind = 'local' | 'wsl' | 'tunneled';\n\n/** 最小 Uri 形状（兼容 vscode.Uri 与测试桩） */\nexport type UriLike = { toString(): string };\n\n/**\n * 远程窗口分类：\n * - undefined/空 → 'local'\n * - 'wsl'（vscode.env.remoteName 的 WSL 值）→ 'wsl'\n * - 其余（ssh-remote/dev-container/codespaces/attached-container/…）→ 'tunneled'\n */\nexport function classifyRemote(name: string | undefined): RemoteKind {\n  if (typeof name !== 'string' || name.trim() === '') return 'local';\n  return name === 'wsl' ? 'wsl' : 'tunneled';\n}\n\n/**\n * 判断窗口是否为远程窗口：vscode.env.remoteName 非空即远程。\n * 空串/未定义视为本地。注意：WSL 也返回 true（它确实是远程窗口形态），\n * 是否可用由 classifyRemote 区分（WSL 不需要隧道、默认放行）。\n */\nexport function isRemoteName(name: string | undefined): boolean {\n  return typeof name === 'string' && name.trim() !== '';\n}\n\n/** 环回主机名集合（WSL host 替换的目标/来源） */\nconst LOOPBACK_HOSTS = new Set(['127.0.0.1', 'localhost', '::1', '[::1]']);\n\n/**\n * 桥接握手超时（毫秒，issue #13-5）：面板打开且服务就绪后，此时间内无 bridgeAck 视为握手失败。\n * - tunneled（SSH Remote/容器，需 asExternalUri 隧道 + iframe 慢载）：15s——\n *   探测 → 隧道解析 → iframe 加载 → DSH 页面 70 个插件 boot（实测 1.5~3s）全链路 5~10s；\n * - local / wsl：5s（wsl 直连加载快；给 DSH 页面 boot 留余量）。\n */\nexport function handshakeTimeoutMs(remoteName: string | undefined): number {\n  return classifyRemote(remoteName) === 'tunneled' ? 15000 : 5000;\n}\n\n/** 桥接状态评估延迟（毫秒）：略大于握手超时，给握手回执留出时间 */\nexport function bridgeEvalDelayMs(remoteName: string | undefined): number {\n  return handshakeTimeoutMs(remoteName) + 1500;\n}\n\n/**\n * 把回环地址的 host 统一替换为 localhost（Windows→WSL 的 localhost 转发依赖该形式）。\n * 非环回 host（如 asExternalUri 的隧道地址）原样返回。\n */\nexport function toLocalhostUrl(url: string): string {\n  try {\n    const u = new URL(url);\n    if (!LOOPBACK_HOSTS.has(u.hostname)) return url;\n    u.hostname = 'localhost';\n    return u.href;\n  } catch {\n    return url;\n  }\n}\n\n/** asExternalUri 注入接口（生产接 vscode.env，测试注入假实现） */\nexport interface ExternalUriApp {\n  asExternalUri(uri: UriLike): Promise<UriLike>;\n}\n\n/**\n * 构造「URL → 本地可达 URL」的解析器。\n * - 本地：asExternalUri 原样返回；\n * - 远程：VS Code 自动建隧道并返回本地 URI；\n * - asExternalUri 抛错时回退原 URL（不中断面板，本地可达场景仍可用）。\n */\nexport function createUrlResolver(app: ExternalUriApp) {\n  return async (url: string): Promise<string> => {\n    try {\n      const r = await app.asExternalUri({ toString: () => url } as UriLike);\n      return r.toString();\n    } catch {\n      return url;\n    }\n  };\n}\n"
    },
    {
      "path": "src/bridge/host.ts",
      "content": "// src/bridge/host.ts — 桥接消息处理：外链打开 / 文件跳转\n// 职责：把 webview 顶层转发来的桥接消息（bridgeOpenExternal / bridgeOpenFile）落地为\n// VS Code 动作（打开外部浏览器 / 打开文本文档），并做协议白名单与路径解析的纵深防御。\n// 依赖注入设计：生产侧接 vscode API（openExternal / showTextDocument），测试侧注入假实现，\n// 保证纯逻辑可被 node:test 直接验证。\nimport { isAbsolute, resolve, join, basename } from 'node:path';\nimport type { PanelMessage } from '../panel/html';\n\n/** 图片缓存文件名白名单正则：前缀（与 core.js 的 imageCacheFilename 一致）+ 时间戳/序号 + 白名单扩展名 */\nconst IMAGE_CACHE_NAME_RE = /^dsh-imgcache-[A-Za-z0-9._:-]+-\\d+\\.(png|jpe?g|gif|webp)$/i;\n\n/**\n * 已落盘图片注册表：仅允许删除「本扩展写过的」缓存文件。\n * 这是纵深防御——即使页面被攻破/伪造 deleteImages 消息的任意路径，也无法删除工作区外的文件。\n * 默认使用模块级共享注册表（主/次面板共享）；测试可注入独立注册表。\n */\nexport interface ImageRegistry {\n  has(p: string): boolean;\n  add(p: string): void;\n  delete(p: string): void;\n  /** 当前登记的全部路径（供全量清理迭代；返回副本，不暴露内部 Set） */\n  all(): string[];\n}\nexport function createImageRegistry(): ImageRegistry {\n  const set = new Set<string>();\n  return {\n    has: (p) => set.has(p),\n    add: (p) => set.add(p),\n    delete: (p) => set.delete(p),\n    all: () => [...set],\n  };\n}\nconst sharedImageRegistry = createImageRegistry();\n\n/** 图片文件写入依赖（生产接 node:fs/promises 的 writeFile/unlink） */\nexport interface ImageFileDeps {\n  writeFile(path: string, dataB64: string): Thenable<void>;\n  rmFile(path: string): Thenable<void>;\n}\n\n/**\n * 安全落盘图片缓存：仅接受绝对 cwd + 白名单文件名（无路径穿越），写入 join(cwd, name)。\n * 成功返回 { ok: true, path } 并登记到注册表；失败返回原因（不抛异常，由调用方回 ack）。\n */\nexport async function saveImageToCwd(\n  deps: ImageFileDeps,\n  req: { cwd?: string; name: string; dataB64: string },\n  registry: ImageRegistry = sharedImageRegistry,\n): Promise<{ ok: boolean; path?: string; error?: string }> {\n  if (typeof req.cwd !== 'string' || req.cwd === '' || !isAbsolute(req.cwd)) {\n    return { ok: false, error: 'invalid cwd' };\n  }\n  // 文件名必须是普通名称（无路径分隔符/穿越）、符合白名单\n  if (typeof req.name !== 'string' || basename(req.name) !== req.name || !IMAGE_CACHE_NAME_RE.test(req.name)) {\n    return { ok: false, error: 'invalid filename' };\n  }\n  const target = join(req.cwd, req.name);\n  // 防御：产物必须是 cwd 内的精确拼接（join 结果）\n  if (target !== resolve(req.cwd, req.name)) {\n    return { ok: false, error: 'path mismatch' };\n  }\n  if (typeof req.dataB64 !== 'string' || req.dataB64 === '') {\n    return { ok: false, error: 'empty data' };\n  }\n  try {\n    await deps.writeFile(target, req.dataB64);\n  } catch (err) {\n    return { ok: false, error: err instanceof Error ? err.message : String(err) };\n  }\n  registry.add(target);\n  return { ok: true, path: target };\n}\n\n/**\n * 删除图片缓存：只删除注册表中「本扩展曾写过的」路径，其余一律忽略。\n * 单个文件删除失败不中断其余；返回 { ok: true }（尽力而为，不因个别失败而整体报错）。\n */\nexport async function deleteImageFiles(\n  deps: ImageFileDeps,\n  req: { paths: string[] },\n  registry: ImageRegistry = sharedImageRegistry,\n): Promise<{ ok: boolean; error?: string }> {\n  const list = Array.isArray(req.paths) ? req.paths : [];\n  for (const p of list) {\n    if (typeof p !== 'string' || !registry.has(p)) continue;\n    try {\n      await deps.rmFile(p);\n    } catch {\n      // 删除失败（文件已被移走/权限）尽力而为，不中断其余\n    } finally {\n      registry.delete(p);\n    }\n  }\n  return { ok: true };\n}\n\n/**\n * 全量清理图片缓存（扩展停用/服务停止时的兜底）：删除注册表中所有已写路径并清空注册表。\n * 补充 pagehide 清理之外的生命周期缺口（关闭 VS Code/停用扩展时页面不一定会触发 pagehide）。\n */\nexport async function cleanupAllImageCaches(\n  deps: ImageFileDeps,\n  registry: ImageRegistry = sharedImageRegistry,\n): Promise<void> {\n  for (const p of registry.all()) {\n    try {\n      await deps.rmFile(p);\n    } catch {\n      // 忽略个别删除失败\n    }\n    registry.delete(p);\n  }\n}\n\n/**\n * 扫描并清理「工作区根目录』中残留的图片降级临时文件（孤儿清理，不依赖注册表）。\n * 背景：dsh-imgcache-* 由扩展按白名单命名落盘到工作区根；若 VS Code/扩展重启，\n * 内存注册表（sharedImageRegistry）丢失，旧文件会成为「无人追踪的孤儿」——\n * cleanupAllImageCaches/deleteImageFiles 都按注册表删除，找不到它们。故在扩展激活\n * 与手动清理命令时按目录扫描，只删除符合 IMAGE_CACHE_NAME_RE（本扩展专属命名空间）的文件。\n * @param readDir 列出目录条目（生产接 node:fs/promises.readdir）\n * @param rmFile 删除文件（生产接 node:fs/promises.unlink）\n * @param roots 要扫描的工作区根目录；缺失/非绝对路径跳过\n * @returns 删除的文件数\n */\nexport async function cleanupStaleImageCaches(\n  readDir: (dir: string) => Promise<string[]>,\n  rmFile: (path: string) => Promise<void>,\n  roots: string[],\n): Promise<number> {\n  let removed = 0;\n  for (const root of roots) {\n    if (typeof root !== 'string' || root === '' || !isAbsolute(root)) continue;\n    let names: string[];\n    try {\n      names = await readDir(root);\n    } catch {\n      continue; // 目录不可读（不存在/权限）跳过\n    }\n    for (const n of names) {\n      if (typeof n === 'string' && IMAGE_CACHE_NAME_RE.test(n)) {\n        try {\n          await rmFile(join(root, n));\n          removed += 1;\n        } catch {\n          // 单个删除失败（文件已被移走/权限）尽力而为\n        }\n      }\n    }\n  }\n  return removed;\n}\n\n/** 桥接消息处理依赖（生产接 vscode API，测试注入假实现） */\nexport interface BridgeMessageDeps {\n  /** 打开外部链接（生产接 vscode.env.openExternal，返回是否成功） */\n  openExternal(url: string): Thenable<boolean>;\n  /** 打开文本文档（生产接 vscode.window.showTextDocument） */\n  openTextDocument(path: string): Thenable<void>;\n  /** 弹用户可见提示（生产接 vscode.window.showWarningMessage，测试注入假实现以断言） */\n  showWarning(msg: string): void;\n  /** 工作区根目录（相对路径解析的兜底基准，生产由扩展入口注入） */\n  workspaceRoot?: string;\n  /** 写入图片缓存文件（生产接 node:fs/promises，产物 base64）——v0.3.0 图片降级用 */\n  writeFile?: (path: string, dataB64: string) => Thenable<void>;\n  /** 删除图片缓存文件（生产接 node:fs/promises）——v0.3.0 会话结束清理用 */\n  rmFile?: (path: string) => Thenable<void>;\n  /** 回执消息投递（生产接 webview.postMessage）——v0.3.0 saveImage/deleteImages 回执 */\n  reply?: (msg: PanelMessage) => Thenable<void>;\n}\n\n/**\n * 提取错误摘要：优先取 Error.message，其余类型做保守的字符串化，兜底空串。\n * 用于把打开失败原因并入用户提示，避免把内部错误对象原样展示。\n */\nfunction errSummary(err: unknown): string {\n  if (err instanceof Error) return err.message;\n  if (typeof err === 'string') return err;\n  if (err === null || err === undefined) return '';\n  return String(err);\n}\n\n/**\n * 解析文件路径：绝对路径直接采用；相对路径依次按 会话 cwd → 工作区根 作为基准解析。\n * 安全规则：形似 URL 的协议串（如 https://、javascript:）一律拒绝，\n * 但 Windows 盘符（C:\\ 或 C:/）不是协议，需要放行。\n */\nexport function resolveBridgePath(raw: string, sessionCwd: string | undefined, workspaceRoot: string | undefined):\n  { kind: 'abs'; path: string } | { kind: 'invalid' } {\n  // 路径形似 URL 一律拒绝（协议串）；Windows 盘符不属于协议，予以放行\n  if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(raw) && !/^[a-zA-Z]:[\\\\/]/.test(raw)) {\n    return { kind: 'invalid' };\n  }\n  // 绝对路径直接采用（跨平台：Windows 盘符与 POSIX / 开头都算绝对）\n  if (isAbsolute(raw)) return { kind: 'abs', path: raw };\n  // 相对路径：优先用会话 cwd，缺失时退回工作区根；两者都无则无法解析\n  const base = sessionCwd ?? workspaceRoot;\n  if (base === undefined) return { kind: 'invalid' };\n  return { kind: 'abs', path: resolve(base, raw) };\n}\n\n/**\n * 处理桥接消息：外链打开走协议白名单，文件跳转走路径解析。\n */\nexport async function handleBridgeMessage(msg: PanelMessage, deps: BridgeMessageDeps): Promise<void> {\n  if (msg.type === 'bridgeOpenExternal') {\n    // 协议白名单：仅 http/https（与桥接侧白名单双重校验，纵深防御）\n    if (/^https?:\\/\\//i.test(msg.url)) {\n      try {\n        await deps.openExternal(msg.url);\n      } catch (err) {\n        // 打开外链可能失败（如无默认浏览器），捕获后给用户可见反馈而非未处理拒绝\n        deps.showWarning(`无法打开链接：${msg.url}（${errSummary(err)}）`);\n      }\n    }\n    return;\n  }\n  if (msg.type === 'bridgeOpenFile') {\n    const r = resolveBridgePath(msg.path, msg.cwd, deps.workspaceRoot);\n    if (r.kind === 'abs') {\n      try {\n        // 打开文档可能因文件不存在/无权限等失败，捕获后给用户可见反馈而非未处理拒绝\n        await deps.openTextDocument(r.path);\n      } catch (err) {\n        // 文案内联固定提示（本模块纯逻辑，直接断言，与 Task 7 的 i18n 无关）\n        deps.showWarning(`无法打开文件：${r.path}（${errSummary(err)}）`);\n      }\n    } else {\n      // 路径无法解析（危险协议或缺少基准目录）：把「缺哪个基准」与出路一起说清楚。\n      // 相对路径（如 a.png）必须有基准：会话 cwd 或 VS Code 工作区根；两者都没有时只能提示改用绝对路径。\n      const reason = msg.missReason !== undefined ? `，会话目录不可用（${msg.missReason}）` : '';\n      const base = deps.workspaceRoot === undefined ? '未打开文件夹' : `工作区根 ${deps.workspaceRoot}`;\n      deps.showWarning(`无法解析路径：${msg.path}（${base}${reason}）——请改用绝对路径，或在 VS Code 中打开该文件所在文件夹`);\n    }\n    return;\n  }\n  if (msg.type === 'bridgeSaveImage') {\n    // 图片缓存落盘：白名单校验 + 路径安全由 saveImageToCwd 保证；回执 success/路径给 iframe\n    // cwd 兜底：客户端通常不传会话 cwd（DSH 无轻量接口可取），回退到工作区根目录（=dsh 会话 cwd 的常用值）\n    const r = await saveImageToCwd(\n      { writeFile: deps.writeFile ?? (async () => {}), rmFile: deps.rmFile ?? (async () => {}) },\n      { cwd: msg.sessionCwd ?? deps.workspaceRoot, name: msg.name, dataB64: msg.dataB64 },\n    );\n    await deps.reply?.({\n      type: 'bridgeSaveImageAck',\n      requestId: msg.requestId,\n      ok: r.ok,\n      ...(r.path === undefined ? {} : { path: r.path }),\n    });\n    return;\n  }\n  if (msg.type === 'bridgeDeleteImages') {\n    // 会话结束清理：只删除注册表中的本扩展缓存文件\n    const r = await deleteImageFiles(\n      { writeFile: deps.writeFile ?? (async () => {}), rmFile: deps.rmFile ?? (async () => {}) },\n      { paths: msg.paths },\n    );\n    await deps.reply?.({ type: 'bridgeDeleteImagesAck', requestId: msg.requestId, ok: r.ok });\n    return;\n  }\n}"
    },
    {
      "path": "src/bridge/installer.ts",
      "content": "// src/bridge/installer.ts — DSH 桥接包的探测与幂等安装/卸载\n// 职责：把 bridge-client 包安装进用户 profile 目录（$DSH_HOME/profiles/<profile>），\n// 并通过 cordis.patch.yml 的 insert: 条目把它注册为 DSH 的官方 client 插件。\n// 安全边界：只写用户目录（$DSH_HOME/profiles/<profile>），绝不触碰 DSH 安装目录。\n//\n// 关键约束（来自 Task 0 spike 实测，见 task-0-report.md）：\n// 1. cordis.patch.yml 顶层是流式空数组 `[]` 时，不能在其后直接追加块序列条目，\n//    否则整个文件 YAML 解析失败（fail-loud）。必须把顶层改写为块序列形式。\n// 2. 新增条目必须用 `insert:` 包裹；裸 `- id:` 条目是「按 id 覆盖既有行」的 patch，\n//    目标行不存在时只会告警并跳过，不会真正新增条目。\n// 3. 卸载时按 begin/end 标记精确删除条目段；若删除后仅剩空白，还原为 `[]`。\nimport { join, dirname, win32 } from 'node:path';\nimport * as nodeFs from 'node:fs';\n\n/** 桥接条目在 cordis.patch.yml 中的包裹标记（卸载时按标记精确删除） */\nexport const BRIDGE_BEGIN_MARK = '# dsh-vscode-bridge: begin';\nexport const BRIDGE_END_MARK = '# dsh-vscode-bridge: end';\n/** 空数组改写分支的元数据标记：begin 标记行携带它，卸载时据此字节级还原「注释头 + []」 */\nexport const BRIDGE_WAS_EMPTY_ARRAY_FLAG = 'was-empty-array';\n/** 空数组改写分支专用 begin 标记（= base begin 标记 + was-empty-array 元数据） */\nexport const BRIDGE_BEGIN_MARK_WAS_EMPTY = `${BRIDGE_BEGIN_MARK} ${BRIDGE_WAS_EMPTY_ARRAY_FLAG}`;\n\n/** 桥接包在 profile node_modules 下的目录名（无 scope） */\nexport const BRIDGE_PACKAGE_NAME = 'dsh-vscode-bridge';\n\n/** 注入的 fs 子集：生产用 Node fs 封装（createNodeFs），测试用内存实现 */\nexport interface InstallerFs {\n  exists(p: string): boolean;\n  readFile(p: string): string;\n  writeFile(p: string, content: string): void;\n  mkdir(p: string): void;\n  copyDir(src: string, dest: string): void;\n  rmDir(p: string): void;\n  readdir(p: string): string[];\n  /** 是否为符号链接（卸载钩子用：跟随链接会写到 $DSH_HOME 之外，必须显式跳过）。\n   *  可选：既有内存 fs 实现与旧调用方无需改动。 */\n  isSymlink?(p: string): boolean;\n}\n\n/** 安装结果状态：ok 成功；pending-restart 预留（服务重启后生效）；degraded 降级 */\nexport type BridgeInstallStatus = 'ok' | 'pending-restart' | 'degraded';\n\n/** 安装结果 */\nexport interface BridgeInstallResult {\n  status: BridgeInstallStatus;\n  reason?: string;   // degraded 时的原因（英文短句，日志用）\n  profileDir?: string;\n  bridgeDir?: string; // primary 路径 profiles/<profile>/node_modules/dsh-vscode-bridge；secondary 见 bridgeTargetDirs\n}\n\n/** 安装参数 */\nexport interface BridgeInstallOptions {\n  profile?: string;          // DSH profile 名称，默认 web\n  dshHome: string;            // $DSH_HOME 或 ~/.dsh\n  bridgeSourceDir: string;    // 插件随附 bridge-client 目录绝对路径\n  fs: InstallerFs;            // 注入的 fs 子集\n  /** npm 全局 node_modules 目录绝对路径（Windows 扩展宿主 ESM 解析可达位置，可选） */\n  npmGlobalNodeModules?: string;\n}\n\n/**\n * 定位所选 profile 目录：dshHome/profiles/<profile>。\n * 不存在时返回 null（调用方据此判定为 degraded）。\n */\nexport function detectProfileDir(dshHome: string, fs: InstallerFs, profile = 'web'): string | null {\n  const dir = join(dshHome, 'profiles', profile);\n  return fs.exists(dir) ? dir : null;\n}\n\n/**\n * 桥接包的全部安装目标目录。\n *\n * 背景（Windows 实测，见 bridge-locations-fix-report.md）：\n * - primary：profiles/<profile>/node_modules/dsh-vscode-bridge（WSL 模块解析锚点）；\n * - secondary：profiles/node_modules/dsh-vscode-bridge（Windows profile 插件解析 fallback 真实目录）；\n * - npm 全局位置（可选）：Windows 下 VS Code 扩展宿主 spawn 的 dsh 进程对 profile 插件的 ESM\n *   解析与普通命令行进程不同，profiles 双位置仍可能解析不到桥接包；而 npm 全局 node_modules\n *   （AppData\\Roaming\\npm\\node_modules）是确定可达的位置，因此额外安装到此处。\n * 两类平台各解析其可及位置，因此需同时安装到全部位置。\n *\n * 顺序固定：[primary, secondary, ...(npmGlobalNodeModules ? [join(npmGlobalNodeModules, NAME)] : [])]\n *\n * @param profileDir            所选 profile 目录绝对路径\n * @param npmGlobalNodeModules  npm 全局 node_modules 目录绝对路径（可选，缺省仅双位置）\n */\nexport function bridgeTargetDirs(profileDir: string, npmGlobalNodeModules?: string): string[] {\n  const dirs = [\n    join(profileDir, 'node_modules', BRIDGE_PACKAGE_NAME),\n    join(profileDir, '..', 'node_modules', BRIDGE_PACKAGE_NAME),\n  ];\n  if (npmGlobalNodeModules) {\n    dirs.push(join(npmGlobalNodeModules, BRIDGE_PACKAGE_NAME));\n  }\n  return dirs;\n}\n\n/**\n * 从「dsh 包内文件路径」向上寻找第一个 `node_modules` 目录（issue #20）。\n *\n * 场景：`dsh.executablePath` 指向 `…\\app.asar.unpacked\\node_modules\\@deepseek-ai\\dsh\\lib\\bin.js`\n * 这类包内入口时，`dirname` 得到的是包内目录而非 node_modules 根；逐级上溯才能拿到真正的根。\n * 全程用 path.win32，避免在非 Windows 上单测这条 Windows 逻辑时被平台路径规则干扰。\n *\n * @returns node_modules 根目录；路径中不含 node_modules 段时返回 undefined（调用方放弃该目标）\n */\nexport function npmNodeModulesRootFrom(p: string): string | undefined {\n  let dir = win32.dirname(p);\n  for (let i = 0; i < 12; i += 1) {\n    if (win32.basename(dir).toLowerCase() === 'node_modules') return dir;\n    const parent = win32.dirname(dir);\n    if (parent === dir) break; // 到盘符根仍未找到\n    dir = parent;\n  }\n  return undefined;\n}\n\n/**\n * 判断该安装目标是否应当跳过：其**父目录是\"命令垫片目录\"**（issue #20）。\n *\n * 关键点（真实文件系统 + 真机验证得出，且踩过一次回归）：\n * 危险不是\"父目录里有别人的东西\"，而是\"**往一个被别的程序独占的命令目录里新增条目**\"。\n * 受害目录 `%APPDATA%\\DSH Desktop\\host-commands\\desktop\\bin` 被 DSH Desktop 以硬断言独占\n * （只允许它自己的 `dsh.cmd`）：多出任何条目（含我们新建的 `dsh-vscode-bridge/`）都会让\n * 桌面下次启动硬失败。\n *\n * 判据刻意收窄为「父目录里存在批处理垫片（`*.cmd`）」——这正是\"命令目录\"的特征：\n * - `…/desktop/bin` 里有 `dsh.cmd` → 跳过 ✅（issue #20 的场景）\n * - `…/node_modules`（npm 全局或 DSH profiles 下的依赖目录）里有成百上千个包，\n *   但不会有 `dsh.cmd` → **放行**，否则桥接无法被刷新（曾因\"父目录有他人条目就跳过\"\n *   导致 `profiles/node_modules` 的桥接停留在旧版本）。\n *\n * @param parentDir 目标目录的父目录（如 `…/node_modules` 或 `…/desktop/bin`）\n */\nexport function shouldSkipForeignTarget(\n  parentDir: string,\n  fs: Pick<InstallerFs, 'exists' | 'readdir'>,\n): boolean {\n  if (!fs.exists(parentDir)) return false; // 父目录不存在：由本扩展创建，安全\n  try {\n    // 只认\"命令垫片目录\"：含 *.cmd 即视为被别的程序独占的命令目录\n    return fs.readdir(parentDir).some((name) => name.toLowerCase().endsWith('.cmd'));\n  } catch {\n    // 读不到目录内容（权限/IO）时保守跳过：宁可少装一处，也不冒写坏他人目录的风险\n    return true;\n  }\n}\n\n/**\n * 判定 cordis.patch.yml 的顶层是否为「流式空数组 []」。\n *\n * 规则：去掉注释行与空行后：\n * - 剩余有效行为空，且原文 trim 后为空 → 空文件，视为空数组；\n * - 剩余有效行只有一行且为 `[]` → 顶层空数组（含「注释 + []」的默认模板）；\n * - 其余（含只有注释、或已有块序列条目）→ 不是空数组。\n *\n * 注意「只有注释」必须走追加分支而非改写分支：注释可能是用户自己的内容\n * （见 uninstall 用例 `# 用户自己的内容`），改写会覆盖它。\n */\nfunction isTopLevelEmptyArray(content: string): boolean {\n  const meaningful = content\n    .split('\\n')\n    .map((l) => l.trim())\n    .filter((l) => l !== '' && !l.startsWith('#'));\n  if (meaningful.length === 0) {\n    // 无任何有效行：只有「真正空文件」才视为空数组；只有注释视为用户内容\n    return content.trim() === '';\n  }\n  return meaningful.length === 1 && meaningful[0] === '[]';\n}\n\n/**\n * 提取「顶层空数组」文件中 `[]` 这一行之前的注释头（含全部注释行与空行），原样保留。\n * 仅在 isTopLevelEmptyArray 判定为真时调用；逐行定位顶层 `[]` 所在行，\n * 返回其之前的原始子串（不 trim、不改写），供卸载时字节级还原。\n */\nfunction findEmptyArrayHead(content: string): string {\n  let pos = 0;\n  for (const line of content.split('\\n')) {\n    if (line.trim() === '[]') {\n      // 找到顶层 [] 行：其之前的内容（注释头 + 空行）即 head\n      return content.slice(0, pos);\n    }\n    pos += line.length + 1; // +1 为换行符\n  }\n  return ''; // 防御分支：调用前已用 isTopLevelEmptyArray 判定，不会走到这里\n}\n\n/**\n * 幂等安装桥接包（全部目标目录：primary + secondary + 可选 npm 全局位置）：\n * - profile 缺失 → degraded；\n * - 条目已存在 → 可用性验证（每处均可读 package.json），全部完好则 ok，\n *   任一处坏包（权限/损坏/缺失）则强制重装该处，重装失败则回滚条目为 degraded；\n * - 首次安装 → 写条目 + 复制目录到全部目标位置，\n *   任一处 copyDir 失败则清理已复制的 → 还原 patch → degraded；\n * - 顶层空数组 → 整文件改写为块序列（含 insert: 条目）；\n * - 已有用户内容 → 去尾随空白后追加 insert: 条目。\n */\nexport function installBridge(opts: BridgeInstallOptions): BridgeInstallResult {\n  const profileDir = detectProfileDir(opts.dshHome, opts.fs, opts.profile);\n  if (profileDir === null) {\n    return { status: 'degraded', reason: `${opts.profile ?? 'web'} profile not found` };\n  }\n  const patchPath = join(profileDir, 'cordis.patch.yml');\n  const allTargets = bridgeTargetDirs(profileDir, opts.npmGlobalNodeModules);\n  // 写入前的白名单校验（issue #20）：按**父目录**判定——父目录里已有非本扩展产物就跳过该目标。\n  // 典型受害目录是 DSH Desktop 的私有命令目录（只允许它自己的 dsh.cmd）：哪怕目标子目录\n  // 还不存在，只要往那里新建 `dsh-vscode-bridge/`，桌面下次启动就会硬失败。\n  const targets = allTargets.filter((t) => !shouldSkipForeignTarget(dirname(t), opts.fs));\n  // primary 路径保持兼容语义（BridgeInstallResult.bridgeDir）\n  const bridgeDir = targets[0] ?? allTargets[0];\n\n  // 读取现有 patch（不存在视为空，避免真实环境首次运行时 readFile 抛错）\n  const existing = opts.fs.exists(patchPath) ? opts.fs.readFile(patchPath) : '';\n\n  if (existing.includes(BRIDGE_BEGIN_MARK)) {\n    // 已存在条目：先把可能出现的重复副本自愈掉（issue #19——重复条目会让 DSH 插件树崩溃），\n    // 再做\"全部目标目录都必须可用\"的判定（能读到含 `\"name\"` 的 package.json，\n    // 且版本与插件随附版本一致——版本不一致说明是升级前的旧包，需强制重装刷新）。\n    // 仅 exists 会漏掉「目录在但 package.json 不可读」的坏包（chmod 000 事故），\n    // 且 Windows 场景某目标缺失但其余完好时也需自愈补回。\n    const deduped = dedupeBridgeEntries(existing);\n    if (deduped !== existing) {\n      opts.fs.writeFile(patchPath, deduped);\n    }\n    const wantVersion = bridgeVersion(opts.bridgeSourceDir, opts.fs);\n    const unusable = targets.filter((t) => !isBridgeUsable(t, opts.fs, wantVersion, opts.bridgeSourceDir));\n    if (unusable.length === 0) {\n      return { status: 'ok', profileDir, bridgeDir };\n    }\n    // 有目标不可用：逐一强制重装（删掉坏目录后重新复制）。\n    try {\n      for (const t of unusable) {\n        opts.fs.rmDir(t);\n        copyBridgeDir(opts, t);\n      }\n      return { status: 'ok', profileDir, bridgeDir };\n    } catch (e) {\n      // 删除或复制失败（权限锁死等）：回滚 patch 条目，避免「有条目但包不可用」导致 DSH 启动失败。\n      // 回滚后 DSH 至少能干净启动，用户可手工修权限后再重试安装。\n      uninstallBridge(opts);\n      return { status: 'degraded', reason: `reinstall failed: ${errMsg(e)}`, profileDir, bridgeDir };\n    }\n  }\n\n  // 首次安装：写条目前保存原文，供 copyDir 失败时回滚，绝不残留「有条目但包不可用」。\n  const originalPatch = existing;\n  writePatchEntry(opts.fs, patchPath, existing);\n  let failedTarget = '';\n  try {\n    // 全部目标位置复制：每处都成功才算安装成功。\n    for (const t of targets) {\n      failedTarget = t;\n      copyBridgeDir(opts, t);\n    }\n  } catch (e) {\n    // 任一处复制失败：尽力清理已复制的目录 + 还原 patch 原文，返回 degraded。\n    // 清理为尽力而为（rmDir 可能同样抛错），核心是还原 patch 绝不残留「有条目但包不可用」。\n    for (const t of targets) {\n      try { opts.fs.rmDir(t); } catch { /* 忽略清理失败 */ }\n    }\n    opts.fs.writeFile(patchPath, originalPatch);\n    // failedTarget 即失败时正在复制的目标路径，写入 reason 便于日志定位。\n    return { status: 'degraded', reason: `copy failed at ${failedTarget}: ${errMsg(e)}`, profileDir, bridgeDir };\n  }\n  return { status: 'ok', profileDir, bridgeDir };\n}\n\n/**\n * 去掉重复的桥接条目，只保留第一段（issue #19）。\n *\n * 现场：多个 VS Code 窗口同时激活、或旧版本残留，会让 cordis.patch.yml 里出现两段\n * `# dsh-vscode-bridge: begin/end`。DSH 侧同一 id 出现多条 insert 会让插件树崩溃\n * （用户报告：必须手工删掉重复项才能进入）。这里做幂等自愈：保留首段、删除后续段落。\n *\n * @returns 去重后的 patch 文本；本来只有一段（或没有）时原样返回\n */\nexport function dedupeBridgeEntries(patch: string): string {\n  if (!patch.includes(BRIDGE_BEGIN_MARK)) return patch;\n  // 逐段提取 begin..end（含标记行本身）；用全局匹配定位所有段落\n  const segRe = new RegExp(\n    `${escapeRegExp(BRIDGE_BEGIN_MARK)}[^\\\\n]*\\\\n[\\\\s\\\\S]*?${escapeRegExp(BRIDGE_END_MARK)}[^\\\\n]*`,\n    'g',\n  );\n  const segs = patch.match(segRe);\n  if (segs === null || segs.length <= 1) return patch;\n  let out = patch;\n  // 从后往前删，避免前面的删除影响后续匹配到的位置\n  for (let i = segs.length - 1; i >= 1; i -= 1) {\n    out = out.replace(segs[i], '');\n  }\n  // 删段后可能留下多余空行：折叠连续 3 个以上换行，避免文件越来越\"松散\"\n  return out.replace(/\\n{3,}/g, '\\n\\n').trimEnd() + '\\n';\n}\n\n/** 转义正则特殊字符（用于把标记文本当字面量匹配） */\nfunction escapeRegExp(s: string): string {\n  return s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\n}\n\n/** 提取 Error 的 message（未知抛出物兜底为字符串化） */\nfunction errMsg(e: unknown): string {\n  return e instanceof Error ? e.message : String(e);\n}\n\n/** 其它 profile 仍注册桥接时保留共享副本；读取失败时也保留，避免破坏其它服务。 */\nfunction hasOtherBridgeProfile(opts: BridgeInstallOptions, profileDir: string): boolean {\n  const profilesDir = dirname(profileDir);\n  try {\n    return opts.fs.readdir(profilesDir).some((name) => {\n      const otherDir = join(profilesDir, name);\n      if (otherDir === profileDir) return false;\n      const patchPath = join(otherDir, 'cordis.patch.yml');\n      return opts.fs.exists(patchPath) && opts.fs.readFile(patchPath).includes(BRIDGE_BEGIN_MARK);\n    });\n  } catch {\n    return true;\n  }\n}\n\n/** 卸载：删除带标记的 insert: 条目段（其余内容原样保留）+ 删除桥接目录 */\nexport function uninstallBridge(opts: BridgeInstallOptions): void {\n  const profileDir = detectProfileDir(opts.dshHome, opts.fs, opts.profile);\n  if (profileDir === null) return;\n  const patchPath = join(profileDir, 'cordis.patch.yml');\n  if (!opts.fs.exists(patchPath)) return;\n  const patch = opts.fs.readFile(patchPath);\n  const begin = patch.indexOf(BRIDGE_BEGIN_MARK);\n  const end = patch.indexOf(BRIDGE_END_MARK);\n  if (begin === -1 || end === -1) return;\n  // 判断是否为空数组改写分支：begin 标记行携带 was-empty-array 元数据。\n  // 只扫描 begin~end 之间的条目段，避免误判用户自身内容里的同名文本。\n  const wasEmptyArray = patch.slice(begin, end).includes(BRIDGE_WAS_EMPTY_ARRAY_FLAG);\n  // 删除 begin 标记行到 end 标记行（含两行及其后随换行），剩余前后内容拼接\n  const restored = patch.slice(0, begin) + patch.slice(end + BRIDGE_END_MARK.length + 1);\n  if (wasEmptyArray) {\n    // 空数组改写分支：restored 即安装前的注释头，补回 []\\n 实现字节级还原\n    opts.fs.writeFile(patchPath, `${restored}[]\\n`);\n  } else {\n    // 用户内容分支：归一化（去掉因追加/删除引入的多余空行与尾随空白）\n    const normalized = restored.trim();\n    if (normalized === '') {\n      // 删除后仅剩空白：原为空数组/空文件，还原为 []\n      opts.fs.writeFile(patchPath, '[]\\n');\n    } else {\n      // 用户内容：去尾随空白后补单个换行，与安装前一致\n      opts.fs.writeFile(patchPath, `${normalized}\\n`);\n    }\n  }\n  const targets = bridgeTargetDirs(profileDir, opts.npmGlobalNodeModules);\n  // 当前 profile 的私有副本始终删除，共享副本仅在最后一个使用者卸载后删除。\n  const removableTargets = hasOtherBridgeProfile(opts, profileDir) ? targets.slice(0, 1) : targets;\n  // 全部目标目录删除均为尽力而为：权限锁死等场景下 rmDir 可能抛错，\n  // 卸载的核心是回滚 patch 条目（保证 DSH 可干净启动），目录删除失败不应中断卸载。\n  for (const dir of removableTargets) {\n    if (opts.fs.exists(dir)) {\n      try {\n        opts.fs.rmDir(dir);\n      } catch {\n        // 忽略：目录残留不影响 DSH 启动，用户可后续手工清理\n      }\n    }\n  }\n}\n\n/**\n * 生产侧 Node fs 适配：把 node:fs 同步 API 封装为 InstallerFs 子集。\n * copyDir 用 fs.cpSync(src, dest, { recursive: true }) 递归复制。\n * 供 Task 7 装配时注入到 installBridge/uninstallBridge。\n */\nexport function createNodeFs(): InstallerFs {\n  return {\n    exists: (p) => nodeFs.existsSync(p),\n    readFile: (p) => nodeFs.readFileSync(p, 'utf8'),\n    writeFile